function templateTasks(skill,level,lang){if(lang==='en')return catalogue[skill][level==='intermediate'?'i':'b'];return (level==='intermediate'?intermediateTasks[skill]?.[lang]:localizedTasks[skill]?.[lang])||catalogue[skill][level==='intermediate'?'i':'b'];}
let plan=null;const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let save=()=>localStorage.setItem('yunet-aignite26-v1',JSON.stringify(plan));function render(){if(!plan)return;$('empty').classList.add('hidden');$('result').classList.remove('hidden');$('resultTitle').textContent=plan.goal+' roadmap';$('intro').textContent=(plan.name?plan.name+', your':'Your')+' practical 4-week learning plan. Each milestone includes focused practice and a deliverable.';$('weeks').textContent='4';$('weekly').textContent=plan.hours+'h';const done=plan.completed.filter(Boolean).length;$('pct').textContent=(done*25)+'%';$('bar').style.width=(done*25)+'%';$('steps').innerHTML=plan.tasks.map((task,i)=>'<article class="step"><div class="checks"><label><input type="checkbox" data-step="'+i+'" '+(plan.completed[i]?'checked':'')+'><span><b><span class="number">'+(i+1)+'</span>Week '+(i+1)+' — '+esc(cleanMilestone(task))+'</b><small>Allocate about '+esc(plan.hours)+' hours this week. Study the topic, practice with a small exercise, and save one visible result.</small></span></label></div></article>').join('');document.querySelectorAll('[data-step]').forEach(el=>el.addEventListener('change',()=>{plan.completed[Number(el.dataset.step)]=el.checked;save();render()}));$('method').textContent=plan.method||'Template-generated study plan. Configure an AI API key on your server for context-aware AI recommendations.';}
$('planner').addEventListener('submit',async e=>{e.preventDefault();const hours=Number($('hours').value);if(!Number.isFinite(hours)||hours<2||hours>40){$('status').textContent='Choose 2–40 hours per week.';return;}const goal=$('goal').value;const level=$('level').value;const fallback=catalogue[goal][level==='beginner'?'b':'i'];plan={skillKey:goal,level,challenge:$('context').value.trim(),language:currentLanguage,aiGenerated:false,name:$('name').value.trim(),goal:catalogue[goal].name,hours,tasks:[...templateTasks(goal,level,currentLanguage)],completed:[false,false,false,false],method:'Template-generated study plan (AI service not configured).'};$('build').disabled=true;$('build').classList.add('is-loading');$('build').setAttribute('aria-busy','true');$('status').textContent='Building your plan…';try{const r=await fetch('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({goal:plan.goal,level,hours,challenge:$('context').value.trim(),language:currentLanguage})});const j=await r.json();if(r.ok&&j.ok&&Array.isArray(j.tasks)&&j.tasks.length===4&&j.tasks.every(x=>typeof x==='string')){plan.tasks=j.tasks;plan.aiGenerated=true;$('status').textContent='';plan.method='AI-personalized roadmap. Review suggestions and verify resources independently.';}else if(j.error==='unconfigured'){$('status').textContent='Preview mode: configure AI service to enable personalization.';}else if(r.status===429){$('status').textContent='AI request limit reached. Your template plan is ready; try AI again later.';}else{$('status').textContent='Using an offline roadmap; AI is temporarily unavailable.';}}catch{$('status').textContent='Using an offline roadmap; AI endpoint unavailable.';}finally{$('build').disabled=false;$('build').classList.remove('is-loading');$('build').setAttribute('aria-busy','false');save();render();}});
$('reset').onclick=()=>{if(confirm(local('confirmReset'))){localStorage.removeItem('yunet-aignite26-v1');plan=null;$('result').classList.add('hidden');$('empty').classList.remove('hidden');$('status').textContent='';summary();}};function output(){return plan.goal+' | 4-week roadmap\n\n'+plan.tasks.map((x,i)=>'Week '+(i+1)+': '+x+' '+(plan.completed[i]?'[Done]':'[To do]')).join('\n')+'\n\nHours per week: '+plan.hours;} $('copy').onclick=async()=>{if(plan){await navigator.clipboard.writeText(output());$('status').textContent='Copied roadmap.';}};$('download').onclick=()=>{if(!plan)return;const blob=new Blob([output()],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='shikhi-ai-roadmap.txt';a.click();URL.revokeObjectURL(a.href)};try{const saved=JSON.parse(localStorage.getItem('yunet-aignite26-v1')||localStorage.getItem('pathpilot-v1'));if(saved&&Array.isArray(saved.tasks)&&saved.tasks.length===4&&Array.isArray(saved.completed)){plan=saved;render()}}catch{}


const win=document.getElementById('desktop'), dim=document.getElementById('dimensions'), scrollArea=document.getElementById('scrollArea');
let maximized=false; const small=()=>innerWidth<=800;const limits=()=>({w:Math.max(300,Math.min(innerWidth,360)),h:Math.min(innerHeight,320)});
function updateDims(){dim.textContent=Math.round(win.getBoundingClientRect().width)+' × '+Math.round(win.getBoundingClientRect().height)}
const obs=new ResizeObserver(updateDims);obs.observe(win);updateDims();
function moveToPixels(){const r=win.getBoundingClientRect();win.style.transform='none';win.style.left=r.left+'px';win.style.top=r.top+'px';win.style.width=r.width+'px';win.style.height=r.height+'px'}
function normal(){maximized=false;win.classList.remove('max');win.style.cssText='';win.style.width=Math.min(1200,innerWidth-16)+'px';win.style.height=Math.min(700,innerHeight-16)+'px';updateDims()}
function maximize(){maximized=true;win.classList.add('max');updateDims()}
document.getElementById('normal').onclick=normal;document.getElementById('maximize').onclick=()=>maximized?normal():maximize();document.getElementById('close').onclick=()=>{win.classList.add('closed');document.getElementById('reopen').classList.remove('hidden')};document.getElementById('reopen').onclick=()=>{win.classList.remove('closed');document.getElementById('reopen').classList.add('hidden');updateDims()};
const header=document.getElementById('titlebar');header.addEventListener('pointerdown',e=>{if(small()||maximized||e.button!==0||e.target.closest('button,input,select,textarea,a'))return;moveToPixels();let x=e.clientX,y=e.clientY,startX=parseFloat(win.style.left),startY=parseFloat(win.style.top);header.setPointerCapture(e.pointerId);const mv=ev=>{win.style.left=Math.max(0,Math.min(innerWidth-win.offsetWidth,startX+ev.clientX-x))+'px';win.style.top=Math.max(0,Math.min(innerHeight-win.offsetHeight,startY+ev.clientY-y))+'px'};const up=()=>{header.removeEventListener('pointermove',mv);header.removeEventListener('pointerup',up)};header.addEventListener('pointermove',mv);header.addEventListener('pointerup',up)});
document.querySelectorAll('[data-edge]').forEach(el=>el.addEventListener('pointerdown',e=>{if(small()||maximized)return;e.preventDefault();moveToPixels();let edge=el.dataset.edge, x=e.clientX,y=e.clientY,r=win.getBoundingClientRect();el.setPointerCapture(e.pointerId);const mv=ev=>{let dx=ev.clientX-x,dy=ev.clientY-y,l=r.left,t=r.top,w=r.width,h=r.height; if(edge.includes('e'))w=Math.max(360,Math.min(innerWidth-l,r.width+dx));if(edge.includes('s'))h=Math.max(320,Math.min(innerHeight-t,r.height+dy));if(edge.includes('w')){l=Math.min(r.right-360,Math.max(0,r.left+dx));w=r.right-l}if(edge.includes('n')){t=Math.min(r.bottom-320,Math.max(0,r.top+dy));h=r.bottom-t}Object.assign(win.style,{left:l+'px',top:t+'px',width:w+'px',height:h+'px'})};const up=()=>{el.removeEventListener('pointermove',mv);el.removeEventListener('pointerup',up)};el.addEventListener('pointermove',mv);el.addEventListener('pointerup',up)}));
function page(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='page-'+id));document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===id));scrollArea.scrollTop=0;summary()};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));document.getElementById('go-planner').onclick=()=>page('roadmap');document.getElementById('progress-open').onclick=()=>page('roadmap');document.getElementById('side-download').onclick=()=>document.getElementById('download').click();document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>{const skill=b.dataset.demo;document.getElementById('goal').value=({'Web development':'web','Data analysis':'data','AI & prompt engineering':'ai'})[skill];document.getElementById('level').value=skill==='AI & prompt engineering'?'intermediate':'beginner';document.getElementById('hours').value=skill==='Data analysis'?8:skill==='Web development'?6:5;document.getElementById('context').value='I want practical projects and a clear weekly deliverable. I prefer free tools and short study sessions.';page('roadmap');document.getElementById('status').textContent='Demo example loaded. Select Build roadmap to generate the plan.';}));
function summary(){let done=plan?.completed?.filter(Boolean).length||0;document.getElementById('footSummary').textContent=plan?done+'/4 milestones · '+plan.goal:'0/4 milestones · No roadmap yet';document.getElementById('progress-summary').textContent=plan?'Completed '+done+' of 4 milestones ('+(done*25)+'%). Goal: '+plan.goal:'Create your first roadmap to start tracking weekly milestones.'}
const oldSave=save;save=()=>{oldSave();summary()}; const oldRender=render;render=()=>{oldRender();summary()};summary();
