function local(key,values={}){let raw=(runtimeDictionary[currentLanguage]||{})[key] || (runtimeDictionary.en||{})[key] || key;return raw.replace(/\{(\w+)\}/g,(_,x)=>String(values[x]??''));}
function goalLabel(goal){return (fullDictionary[currentLanguage]||{})[goal]||goal;}
function translateAll(lang){
 currentLanguage=lang;
 document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
 document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang))});
 const area=document.getElementById('scrollArea');area.dir=lang==='ar'?'rtl':'ltr';
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 while(walker.nextNode()){
  const n=walker.currentNode,el=n.parentElement;
  if(!el||['SCRIPT','STYLE','NOSCRIPT'].includes(el.tagName)||el.closest('.lang,.sticker-img')||el.closest('[contenteditable]'))continue;
  const raw=originals.has(n)?originals.get(n):n.textContent;
  if(!originals.has(n))originals.set(n,raw);
  const trimmed=raw.trim();if(!trimmed)continue;
  const dict=fullDictionary[lang]||{};const val=dict[trimmed];
  if(val!==undefined)n.textContent=raw.replace(trimmed,val);
  else n.textContent=raw;
 }
 document.querySelectorAll('[placeholder],[title],[aria-label]').forEach(el=>{
  for(const attr of ['placeholder','title','aria-label']){
   const value=el.getAttribute(attr);if(!value)continue;
