   el.setAttribute(attr,(fullDictionary[lang]||{})[el.dataset[id]]||el.dataset[id]);
  }
 });
 document.querySelectorAll('[data-i18n]').forEach(el=>{const val=(translations[lang]||translations.en)[el.dataset.i18n];if(val){el.textContent=val; originals.set(el.firstChild,el.dataset.i18nOriginal||translations.en[el.dataset.i18n]||val)}});
 document.title='Shikhi AI | '+({en:'Learning & Career',bn:'শেখা ও ক্যারিয়ার',ar:'التعلم والمسار المهني',nl:'Leren en loopbaan',de:'Lernen und Karriere'}[lang]);
 if(plan){if(plan.aiGenerated && plan.language!==lang)translateAiTasks(lang);if(!plan.aiGenerated && !plan.imported && plan.skillKey && plan.language!==lang){const entries=(localizedTasks[plan.skillKey]||{})[lang];if(entries){plan.tasks=[...entries];plan.language=lang;save()}}renderLocalizedPlan();}summaryLocalized();
 try{localStorage.setItem('yunet-language',lang)}catch{};const state=document.getElementById('appstate');state.textContent=(fullDictionary[lang]||{})[navigator.onLine?'● Online-ready · Browser storage':'○ Offline · Local roadmap'] || (navigator.onLine?'● Online-ready · Browser storage':'○ Offline · Local roadmap');
}
let translateRequest=0;
async function translateAiTasks(lang){
 if(!plan||!plan.aiGenerated||plan.language===lang)return;
 const request=++translateRequest;const samePlan=plan;
 document.getElementById('status').textContent=local('building');
 try{const response=await fetch('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'translate_tasks',tasks:plan.tasks,language:lang})});const data=await response.json();if(request!==translateRequest||plan!==samePlan||currentLanguage!==lang)return;
 if(response.ok&&data.ok&&Array.isArray(data.tasks)&&data.tasks.length===4){plan.tasks=data.tasks;plan.language=lang;save();renderLocalizedPlan();summaryLocalized();document.getElementById('status').textContent='';}
 else document.getElementById('status').textContent=local('apiUnavailable');
 }catch{if(request===translateRequest)document.getElementById('status').textContent=local('networkUnavailable')}
}
function renderLocalizedPlan(){
 if(!plan)return;
 const done=plan.completed.filter(Boolean).length;document.getElementById('pct').textContent=(done*25)+'%';document.getElementById('bar').style.width=(done*25)+'%';
 const goal=goalLabel(plan.goal);
 document.getElementById('resultTitle').textContent=goal+' — '+local('roadmap');
 document.getElementById('intro').textContent=local('intro',{name:plan.name?plan.name+' · ':''});
 document.getElementById('weekly').textContent=plan.hours+({bn:' ঘণ্টা',ar:' ساعة',nl:' u',de:' Std.',en:'h'}[currentLanguage]);
 document.getElementById('steps').innerHTML=plan.tasks.map((task,i)=>'<article class="step"><label><input type="checkbox" data-step="'+i+'" '+(plan.completed[i]?'checked':'')+'><span><b><span class="number">'+(i+1)+'</span>'+local('week')+' '+(i+1)+' — '+esc(cleanMilestone(task))+'</b><small>'+esc(local('hoursTip',{hours:plan.hours}))+'</small></span></label></article>').join('');
 document.querySelectorAll('[data-step]').forEach(el=>el.addEventListener('change',()=>{plan.completed[Number(el.dataset.step)]=el.checked;save();renderLocalizedPlan();summaryLocalized()}));
 document.getElementById('method').textContent=plan.aiGenerated?local('aiMethod'):local('fallback');
}
