 document.getElementById('footSummary').textContent=plan?local('footerPlan',{done,goal:goalLabel(plan.goal)}):local('footerNone');
 document.getElementById('progress-summary').textContent=plan?local('progressLine',{done,pct:done*25,goal:goalLabel(plan.goal)}):local('noPlan');
}
