function localizedMessages(){const status=document.getElementById('status');const msg=status.textContent;const lookup={'Choose 2–40 hours per week.':'validation','Building your plan…':'building','Preview mode: configure AI service to enable personalization.':'unconfigured','Using an offline roadmap; AI is temporarily unavailable.':'apiUnavailable','Using an offline roadmap; AI endpoint unavailable.':'networkUnavailable','Copied roadmap.':'copied','Demo example loaded. Select Build roadmap to generate the plan.':'demoLoaded'};if(lookup[msg]){const next=local(lookup[msg]);if(next!==msg)status.textContent=next;}}
