// v7: canonical English baseline, captured BEFORE any translation. Never translate a prior translation.
const canonicalText=[];
const canonicalAttrs=[];
const walkCanonical=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
while(walkCanonical.nextNode()){
 const n=walkCanonical.currentNode, parent=n.parentElement;
 if(!parent||['SCRIPT','STYLE','NOSCRIPT'].includes(parent.tagName)||parent.closest('.lang')||!n.textContent.trim())continue;
 canonicalText.push({node:n,raw:n.textContent,english:n.textContent.trim()});
}
document.querySelectorAll('[placeholder],[title],[aria-label]').forEach(el=>{
 for(const a of ['placeholder','title','aria-label'])if(el.hasAttribute(a))canonicalAttrs.push({el,attr:a,en:el.getAttribute(a)});
});
const canonicalTagValues=new Map();
document.querySelectorAll('[data-i18n]').forEach(el=>canonicalTagValues.set(el,el.dataset.i18n));
const originalLanguageSwitcher=translateAll;
translateAll=function(lang){
 if(!['en','bn','ar','nl','de'].includes(lang))lang='en';
 currentLanguage=lang;document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
 document.getElementById('scrollArea').dir=lang==='ar'?'rtl':'ltr';
 document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang));});
 const dictionary=fullDictionary[lang]||{};
 // Use *only* the captured English source to avoid mixed-language switch bugs.
 for(const item of canonicalText){
  if(!item.node.isConnected)continue;
  let translated=dictionary[item.english];
  const key=canonicalTagValues.get(item.node.parentElement);
  if(key&&translations[lang]?.[key]!==undefined)translated=translations[lang][key];
  if(translated===undefined)translated=item.english;
  item.node.textContent=item.raw.replace(item.english,translated);
 }
 for(const item of canonicalAttrs){if(item.el.isConnected)item.el.setAttribute(item.attr,dictionary[item.en]??item.en);}
 // Translate all keyed items, including those not made of simple text nodes.
 document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(translations[lang]?.[key]!==undefined){el.textContent=translations[lang][key];}});
 // Explicit translated headings that were previously left in English.
 const h=document.querySelector('#page-dashboard .hero h1');if(h)h.textContent=translations[lang].hero;
 document.title='Shikhi AI | '+({en:'Learning & Career',bn:'শেখা ও ক্যারিয়ার',ar:'التعلم والمسار المهني',nl:'Leren en loopbaan',de:'Lernen und Karriere'}[lang]);
 if(plan){if(plan.aiGenerated&&plan.language!==lang)translateAiTasks(lang);else if(!plan.aiGenerated&&!plan.imported&&plan.skillKey&&plan.language!==lang){let tasks=templateTasks(plan.skillKey,plan.level||'beginner',lang);if(tasks){plan.tasks=[...tasks];plan.language=lang;save();}}renderLocalizedPlan();}
 summaryLocalized();
 const state=document.getElementById('appstate');state.textContent=dictionary[navigator.onLine?'● Online-ready · Browser storage':'○ Offline · Local roadmap']||(navigator.onLine?'● Online-ready · Browser storage':'○ Offline · Local roadmap');
 try{localStorage.setItem('yunet-language',lang)}catch{}
};

