// Keep each roadmap independently, including its completion checkmarks.
const plansStorageKey='shikhi-ai-plans-v1';
let savedPlans=[];
function validSavedPlan(p){return p&&typeof p.id==='string'&&typeof p.goal==='string'&&Array.isArray(p.tasks)&&p.tasks.length===4&&p.tasks.every(t=>typeof t==='string')&&Array.isArray(p.completed)&&p.completed.length===4;}
try{const stored=JSON.parse(localStorage.getItem(plansStorageKey)||'[]');if(Array.isArray(stored))savedPlans=stored.filter(validSavedPlan);}catch{}
function planId(){return typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);}
function archiveCurrentPlan(){
 if(!plan)return;
 if(!plan.id)plan.id=planId();
 if(!plan.createdAt)plan.createdAt=new Date().toISOString();
 plan.updatedAt=new Date().toISOString();
 const snapshot=JSON.parse(JSON.stringify(plan));
 const index=savedPlans.findIndex(p=>p.id===plan.id);
 if(index<0)savedPlans.unshift(snapshot);else savedPlans[index]=snapshot;
 localStorage.setItem(plansStorageKey,JSON.stringify(savedPlans));
}
const saveCurrentPlan=save;
save=function(){archiveCurrentPlan();saveCurrentPlan();renderSavedPlans();};
const deletePlanLabels={en:{remove:'Delete',confirm:'Delete this saved plan? This also removes its progress.'},bn:{remove:'মুছুন',confirm:'এই সংরক্ষিত পরিকল্পনা ও এর অগ্রগতি মুছবেন?'},ar:{remove:'حذف',confirm:'هل تريد حذف هذه الخطة المحفوظة وتقدمها؟'},nl:{remove:'Verwijderen',confirm:'Dit opgeslagen plan en de voortgang verwijderen?'},de:{remove:'Löschen',confirm:'Diesen gespeicherten Plan und seinen Fortschritt löschen?'}};
const savedPlanLabels={
 en:{tab:'◷ Saved plans',title:'Saved plans',description:'Your roadmaps and progress are saved automatically in this browser. Open a plan to continue learning.',empty:'No saved plans yet. Generate your first roadmap to save it here.',open:'Open plan',create:'Create a new plan',saved:'plans saved',hours:'hours/week',complete:'completed',created:'Created',active:'Current plan'},
 bn:{tab:'◷ সংরক্ষিত পরিকল্পনা',title:'সংরক্ষিত পরিকল্পনা',description:'আপনার রোডম্যাপ ও অগ্রগতি এই ব্রাউজারে স্বয়ংক্রিয়ভাবে সংরক্ষিত হয়। শেখা চালিয়ে যেতে পরিকল্পনা খুলুন।',empty:'এখনো কোনো পরিকল্পনা নেই। প্রথম রোডম্যাপ তৈরি করুন।',open:'পরিকল্পনা খুলুন',create:'নতুন পরিকল্পনা তৈরি',saved:'টি পরিকল্পনা সংরক্ষিত',hours:'ঘণ্টা/সপ্তাহ',complete:'সম্পন্ন',created:'তৈরি',active:'বর্তমান পরিকল্পনা'},
 ar:{tab:'◷ الخطط المحفوظة',title:'الخطط المحفوظة',description:'تُحفظ خططك وتقدمك تلقائيًا في هذا المتصفح. افتح خطة لمواصلة التعلم.',empty:'لا توجد خطط محفوظة بعد. أنشئ خطتك الأولى.',open:'افتح الخطة',create:'إنشاء خطة جديدة',saved:'خطط محفوظة',hours:'ساعة/أسبوع',complete:'مكتمل',created:'تاريخ الإنشاء',active:'الخطة الحالية'},
 nl:{tab:'◷ Opgeslagen plannen',title:'Opgeslagen plannen',description:'Je leerplannen en voortgang worden automatisch in deze browser bewaard. Open een plan om verder te leren.',empty:'Nog geen opgeslagen plannen. Maak je eerste leerplan.',open:'Plan openen',create:'Nieuw plan maken',saved:'plannen opgeslagen',hours:'uur/week',complete:'voltooid',created:'Gemaakt',active:'Huidig plan'},
 de:{tab:'◷ Gespeicherte Pläne',title:'Gespeicherte Pläne',description:'Deine Lernpläne und Fortschritte werden automatisch in diesem Browser gespeichert. Öffne einen Plan zum Weiterlernen.',empty:'Noch keine gespeicherten Pläne. Erstelle deinen ersten Lernplan.',open:'Plan öffnen',create:'Neuen Plan erstellen',saved:'Pläne gespeichert',hours:'Std./Woche',complete:'abgeschlossen',created:'Erstellt',active:'Aktueller Plan'}
};
const savedNav=document.createElement('button');savedNav.type='button';savedNav.dataset.page='saved';savedNav.id='saved-plans-tab';
document.querySelector('[data-page="progress"]').insertAdjacentElement('afterend',savedNav);
const savedView=document.createElement('section');savedView.id='page-saved';savedView.className='view';
savedView.innerHTML='<div class="panel"><h2 id="saved-plans-title"></h2><p id="saved-plans-description"></p><p id="saved-plan-count" aria-live="polite"></p><button type="button" id="saved-create-plan"></button><div id="saved-plan-list" class="saved-plan-list"></div></div>';
document.getElementById('scrollArea').appendChild(savedView);
savedNav.onclick=()=>{page('saved');renderSavedPlans();};
document.getElementById('saved-create-plan').onclick=()=>{page('roadmap');document.getElementById('goal').focus();};
function renderSavedPlans(){
 const labels=savedPlanLabels[currentLanguage]||savedPlanLabels.en;const deleteLabels=deletePlanLabels[currentLanguage]||deletePlanLabels.en;
 savedNav.textContent=labels.tab;
 document.getElementById('saved-plans-title').textContent=labels.title;
 document.getElementById('saved-plans-description').textContent=labels.description;
 document.getElementById('saved-plan-count').textContent=savedPlans.length+' '+labels.saved;
 document.getElementById('saved-create-plan').textContent=labels.create;
 const list=document.getElementById('saved-plan-list');
 if(!savedPlans.length){list.innerHTML='<div class="saved-plan-empty">'+esc(labels.empty)+'</div>';return;}
 list.innerHTML=savedPlans.map(p=>{
  const done=p.completed.filter(Boolean).length;const created=new Date(p.createdAt);const date=Number.isNaN(created.getTime())?'':created.toLocaleString(currentLanguage);
  return '<article class="saved-plan-card"><h3>'+esc(goalLabel(p.goal))+'</h3><p>'+esc(p.hours)+' '+esc(labels.hours)+' · '+done+'/4 '+esc(labels.complete)+(p.id===plan?.id?' · '+esc(labels.active):'')+'</p><small>'+esc(labels.created)+': '+esc(date)+'</small><div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+done*25+'" aria-label="'+esc(labels.complete)+'"><div class="bar" style="width:'+done*25+'%"></div></div><p>'+esc(p.tasks[0])+'</p><button type="button" data-open-plan="'+esc(p.id)+'" '+(document.getElementById('build').disabled?'disabled':'')+'>'+esc(labels.open)+'</button><button type="button" class="delete-plan" data-delete-plan="'+esc(p.id)+'" '+(document.getElementById('build').disabled?'disabled':'')+'>'+esc(deleteLabels.remove)+'</button></article>';
 }).join('');
 list.querySelectorAll('[data-delete-plan]').forEach(button=>button.onclick=()=>{
  if(document.getElementById('build').disabled)return;
  const selected=savedPlans.find(p=>p.id===button.dataset.deletePlan);if(!selected)return;
  if(!confirm(deleteLabels.confirm+'\n\n'+goalLabel(selected.goal)))return;
  savedPlans=savedPlans.filter(p=>p.id!==selected.id);
  localStorage.setItem(plansStorageKey,JSON.stringify(savedPlans));
  if(plan?.id===selected.id){
   plan=null;localStorage.removeItem('yunet-aignite26-v1');localStorage.removeItem('pathpilot-v1');
   document.getElementById('result').classList.add('hidden');document.getElementById('empty').classList.remove('hidden');
   document.getElementById('status').textContent='';summaryLocalized();
  }
  renderSavedPlans();
 });
 list.querySelectorAll('[data-open-plan]').forEach(button=>button.onclick=()=>{
  if(document.getElementById('build').disabled)return;
  const selected=savedPlans.find(p=>p.id===button.dataset.openPlan);if(!selected)return;
  plan=JSON.parse(JSON.stringify(selected));
  document.getElementById('name').value=plan.name||'';
  document.getElementById('goal').value=plan.skillKey||'web';
  document.getElementById('level').value=plan.level||'beginner';
  document.getElementById('hours').value=plan.hours;
  document.getElementById('context').value=plan.challenge||'';
  document.getElementById('status').textContent='';
  saveCurrentPlan();page('roadmap');render();
 });
}
const translateWithSavedPlans=translateAll;
translateAll=function(lang){translateWithSavedPlans(lang);renderSavedPlans();};
if(plan){archiveCurrentPlan();saveCurrentPlan();}
renderSavedPlans();


const progressLabels={
 en:{title:'Your learning progress',intro:'Track completed milestones across all your saved plans.',milestones:'milestones completed',total:'Total plans',active:'Active plans',complete:'Completed plans',next:'Next milestone',continue:'Continue',review:'Review plan',finished:'All four milestones completed. Well done!',empty:'Your progress starts with your first plan.',create:'Create a plan',note:'Progress reflects completed milestones, not skill mastery.',of:'of'},
 bn:{title:'আপনার শেখার অগ্রগতি',intro:'সব সংরক্ষিত পরিকল্পনার সম্পন্ন লক্ষ্য একসঙ্গে দেখুন।',milestones:'লক্ষ্য সম্পন্ন',total:'মোট পরিকল্পনা',active:'চলমান পরিকল্পনা',complete:'সম্পন্ন পরিকল্পনা',next:'পরবর্তী লক্ষ্য',continue:'চালিয়ে যান',review:'পরিকল্পনা দেখুন',finished:'চারটি লক্ষ্যই সম্পন্ন। অভিনন্দন!',empty:'প্রথম পরিকল্পনা দিয়ে অগ্রগতি শুরু করুন।',create:'পরিকল্পনা তৈরি',note:'এই অগ্রগতি কাজ সম্পন্ন হওয়ার হিসাব, দক্ষতার পরিমাপ নয়।',of:'এর মধ্যে'},
 ar:{title:'تقدمك في التعلم',intro:'تابع الأهداف المكتملة في جميع خططك المحفوظة.',milestones:'الأهداف المكتملة',total:'إجمالي الخطط',active:'خطط نشطة',complete:'خطط مكتملة',next:'الهدف التالي',continue:'متابعة',review:'مراجعة الخطة',finished:'أكملت الأهداف الأربعة. أحسنت!',empty:'ابدأ تقدمك بإنشاء خطتك الأولى.',create:'إنشاء خطة',note:'يعكس التقدم إكمال الأهداف وليس إتقان المهارة.',of:'من'},
 nl:{title:'Jouw leervoortgang',intro:'Volg voltooide doelen in al je opgeslagen plannen.',milestones:'doelen voltooid',total:'Alle plannen',active:'Actieve plannen',complete:'Voltooide plannen',next:'Volgend doel',continue:'Doorgaan',review:'Plan bekijken',finished:'Alle vier doelen voltooid. Goed gedaan!',empty:'Je voortgang begint met je eerste plan.',create:'Plan maken',note:'Voortgang meet voltooide doelen, geen vaardigheidsbeheersing.',of:'van'},
 de:{title:'Dein Lernfortschritt',intro:'Verfolge erreichte Ziele in allen gespeicherten Plänen.',milestones:'Ziele erreicht',total:'Alle Pläne',active:'Aktive Pläne',complete:'Abgeschlossene Pläne',next:'Nächstes Ziel',continue:'Fortsetzen',review:'Plan ansehen',finished:'Alle vier Ziele erreicht. Gut gemacht!',empty:'Dein Fortschritt beginnt mit deinem ersten Plan.',create:'Plan erstellen',note:'Fortschritt zeigt abgeschlossene Ziele, nicht die Beherrschung einer Fähigkeit.',of:'von'}
};
const progressView=document.getElementById('page-progress');
progressView.innerHTML='<div class="panel"><h2 id="progress-overview-title"></h2><p id="progress-overview-intro"></p><div class="progress-overview"><div class="overall-ring" id="overall-progress-ring" role="progressbar" aria-valuemin="0" aria-valuemax="100"><div class="overall-ring-inner"><strong id="overall-progress-percent">0%</strong><span id="overall-progress-label"></span></div></div><div><div class="progress-counts"><div><strong id="progress-total-plans">0</strong><span id="progress-total-label"></span></div><div><strong id="progress-active-plans">0</strong><span id="progress-active-label"></span></div><div><strong id="progress-completed-plans">0</strong><span id="progress-completed-label"></span></div></div><p id="progress-milestone-total"></p><small id="progress-measure-note"></small></div></div><div id="progress-all-plans" class="progress-plan-list"></div><p id="progress-summary" class="sr-only"></p></div>';
function openProgressPlan(id){
 if(document.getElementById('build').disabled)return;
 const selected=savedPlans.find(p=>p.id===id);if(!selected)return;
 plan=JSON.parse(JSON.stringify(selected));
 document.getElementById('name').value=plan.name||'';document.getElementById('goal').value=plan.skillKey||'web';
 document.getElementById('level').value=plan.level||'beginner';document.getElementById('hours').value=plan.hours;
 document.getElementById('context').value=plan.challenge||'';document.getElementById('status').textContent='';
 saveCurrentPlan();page('roadmap');render();
}
function renderProgressOverview(){
 const labels=progressLabels[currentLanguage]||progressLabels.en;
 const total=savedPlans.length;const milestones=total*4;
 const done=savedPlans.reduce((sum,p)=>sum+p.completed.filter(Boolean).length,0);
 const completed=savedPlans.filter(p=>p.completed.every(Boolean)).length;
 const percent=milestones?Math.round(done/milestones*100):0;
 const footerWords={en:['milestones','plan','plans'],bn:['লক্ষ্য','পরিকল্পনা','পরিকল্পনা'],ar:['أهداف','خطة','خطط'],nl:['doelen','plan','plannen'],de:['Meilensteine','Plan','Pläne']}[currentLanguage]||['milestones','plan','plans'];
 document.getElementById('footSummary').textContent=done+'/'+milestones+' '+footerWords[0]+' · '+total+' '+footerWords[total===1?1:2];
 document.getElementById('progress-overview-title').textContent=labels.title;
 document.getElementById('progress-overview-intro').textContent=labels.intro;
 document.getElementById('overall-progress-percent').textContent=percent+'%';
 document.getElementById('overall-progress-label').textContent=labels.milestones;
 const ring=document.getElementById('overall-progress-ring');ring.style.setProperty('--percent',percent);ring.setAttribute('aria-valuenow',String(percent));ring.setAttribute('aria-label',labels.milestones);
 for(const [id,value] of [['total',total],['active',total-completed],['completed',completed]])document.getElementById('progress-'+id+'-plans').textContent=value;
 document.getElementById('progress-total-label').textContent=labels.total;
 document.getElementById('progress-active-label').textContent=labels.active;
 document.getElementById('progress-completed-label').textContent=labels.complete;
 document.getElementById('progress-milestone-total').textContent=done+' / '+milestones+' '+labels.milestones;
 document.getElementById('progress-measure-note').textContent=labels.note;
 const list=document.getElementById('progress-all-plans');
 if(!total){list.innerHTML='<div class="saved-plan-empty"><p>'+esc(labels.empty)+'</p><button type="button" id="progress-create-first">'+esc(labels.create)+'</button></div>';document.getElementById('progress-create-first').onclick=()=>page('roadmap');return;}
 list.innerHTML=savedPlans.map(p=>{const count=p.completed.filter(Boolean).length;const next=p.completed.findIndex(v=>!v);return '<article class="saved-plan-card progress-plan-card"><div class="progress-plan-heading"><h3>'+esc(goalLabel(p.goal))+'</h3><span>'+count+'/4 · '+count*25+'%</span></div><div class="progress" role="progressbar" aria-label="'+esc(goalLabel(p.goal))+'" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+count*25+'"><div class="bar" style="width:'+count*25+'%"></div></div>'+(next<0?'<p>'+esc(labels.finished)+'</p>':'<span class="progress-next-label">'+esc(labels.next)+' · '+esc(local('week'))+' '+(next+1)+'</span><p>'+esc(p.tasks[next])+'</p>')+'<button type="button" data-progress-plan="'+esc(p.id)+'" '+(document.getElementById('build').disabled?'disabled':'')+'>'+esc(next<0?labels.review:labels.continue)+'</button></article>';}).join('');
 list.querySelectorAll('[data-progress-plan]').forEach(button=>button.onclick=()=>openProgressPlan(button.dataset.progressPlan));
}
const summaryBeforeOverview=summaryLocalized;
summaryLocalized=function(){summaryBeforeOverview();renderProgressOverview();};
const savedBeforeOverview=renderSavedPlans;
renderSavedPlans=function(){savedBeforeOverview();renderProgressOverview();};
const translateBeforeOverview=translateAll;
translateAll=function(lang){translateBeforeOverview(lang);renderProgressOverview();};
document.querySelector('[data-page="progress"]').onclick=()=>{page('progress');renderProgressOverview();};
renderProgressOverview();


const importLabels={en:{button:'Import plan',success:'Plan imported and saved.',error:'Choose a valid exported roadmap (.txt or .json) with four milestones and 2–40 hours per week.',busy:'Wait for roadmap generation to finish.'},bn:{button:'পরিকল্পনা আমদানি',success:'পরিকল্পনা আমদানি ও সংরক্ষণ হয়েছে।',error:'চারটি লক্ষ্য ও সপ্তাহে ২–৪০ ঘণ্টাসহ বৈধ .txt বা .json রোডম্যাপ বাছুন।',busy:'রোডম্যাপ তৈরি শেষ হওয়া পর্যন্ত অপেক্ষা করুন।'},ar:{button:'استيراد خطة',success:'تم استيراد الخطة وحفظها.',error:'اختر ملف خطة صالحًا بصيغة .txt أو .json بأربعة أهداف و٢–٤٠ ساعة أسبوعيًا.',busy:'انتظر اكتمال إنشاء الخطة.'},nl:{button:'Plan importeren',success:'Plan geïmporteerd en opgeslagen.',error:'Kies een geldig .txt- of .json-plan met vier doelen en 2–40 uur per week.',busy:'Wacht tot het leerplan klaar is.'},de:{button:'Plan importieren',success:'Plan importiert und gespeichert.',error:'Wähle einen gültigen .txt- oder .json-Plan mit vier Zielen und 2–40 Stunden pro Woche.',busy:'Warte, bis der Lernplan fertig ist.'}};
const importButton=document.createElement('button');importButton.type='button';importButton.id='import-plan';
document.getElementById('side-download').insertAdjacentElement('beforebegin',importButton);
const importInput=document.createElement('input');importInput.type='file';importInput.accept='.txt,.json,text/plain,application/json';importInput.id='import-plan-file';importInput.hidden=true;importInput.setAttribute('aria-label','Import plan file');importButton.insertAdjacentElement('afterend',importInput);
const importStatus=document.createElement('p');importStatus.id='import-plan-status';importStatus.setAttribute('role','status');document.getElementById('saved-create-plan').insertAdjacentElement('afterend',importStatus);
function importedSkill(goal){for(const [key,entry] of Object.entries(catalogue)){if(entry.name===goal)return key;for(const dictionary of Object.values(fullDictionary))if(dictionary[entry.name]===goal)return key;}return null;}
function parseImportedPlan(text){
 if(typeof text!=='string'||text.length>65536)throw Error('invalid');
 let data;
 if(text.trim().startsWith('{')){data=JSON.parse(text);if(data.plan)data=data.plan;}
 else{
  const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/);const goal=lines[0].split('|')[0].trim();
  const matches=lines.map(line=>line.match(/^.+?\s+(\d+)\s*:\s*(.+?)\s*\[([^\]]+)\]\s*$/)).filter(Boolean);
  if(matches.length!==4||matches.some((m,i)=>Number(m[1])!==i+1))throw Error('invalid');
  const hoursLine=lines.filter(l=>l.trim()).pop();const hoursMatch=hoursLine.match(/:\s*(\d+(?:\.\d+)?)\s*$/);
  data={goal,tasks:matches.map(m=>m[2]),completed:matches.map(m=>['Done','সম্পন্ন','منجز','Voltooid','Erledigt'].includes(m[3].trim())),hours:hoursMatch?Number(hoursMatch[1]):NaN};
 }
 if(!data||typeof data.goal!=='string'||!Array.isArray(data.tasks)||data.tasks.length!==4||data.tasks.some(t=>typeof t!=='string'||!t.trim()||t.length>2000)||!Number.isFinite(Number(data.hours))||Number(data.hours)<2||Number(data.hours)>40)throw Error('invalid');
 const skill=importedSkill(data.goal)||(Object.hasOwn(catalogue,data.skillKey||'')?data.skillKey:null);if(!skill)throw Error('invalid');
 if(data.completed!==undefined&&(!Array.isArray(data.completed)||data.completed.length!==4||data.completed.some(v=>typeof v!=='boolean')))throw Error('invalid');
 return {id:planId(),skillKey:skill,goal:catalogue[skill].name,level:data.level==='intermediate'?'intermediate':'beginner',hours:Number(data.hours),tasks:data.tasks.map(t=>t.trim()),completed:data.completed||[false,false,false,false],name:typeof data.name==='string'?data.name.slice(0,60):'',challenge:typeof data.challenge==='string'?data.challenge.slice(0,400):'',language:['en','bn','ar','nl','de'].includes(data.language)?data.language:currentLanguage,aiGenerated:data.aiGenerated===true,createdAt:new Date().toISOString(),imported:true};
}
importButton.onclick=()=>{const labels=importLabels[currentLanguage]||importLabels.en;if(document.getElementById('build').disabled){importStatus.textContent=labels.busy;return;}importInput.value='';importInput.click();};
importInput.onchange=async()=>{
 const labels=importLabels[currentLanguage]||importLabels.en;const file=importInput.files?.[0];if(!file)return;
 try{if(document.getElementById('build').disabled){importStatus.textContent=labels.busy;return;}if(file.size>65536||!/\.(txt|json)$/i.test(file.name))throw Error('invalid');const imported=parseImportedPlan(await file.text());if(document.getElementById('build').disabled){importStatus.textContent=labels.busy;return;}if(plan)save();plan=imported;save();render();page('saved');importStatus.textContent=labels.success;}
 catch{importStatus.textContent=labels.error;}
};
function renderImportButton(){importButton.textContent=(importLabels[currentLanguage]||importLabels.en).button;}
const translateBeforeImport=translateAll;translateAll=function(lang){translateBeforeImport(lang);renderImportButton();};renderImportButton();

</script></body></html>